/**
 * ?record: frame-perfect video of the guided tour. The app clock becomes
 * virtual and only advances when the driver (tools/record.mjs) asks for the
 * next frame, so the result does not depend on how fast the machine renders:
 * a software-rendering virtual machine and an RTX 5090 produce the same
 * video, only at different speeds.
 */
import type { App } from './app';

export interface Recorder {
  start: () => void;
  step: (dt: number) => boolean;
  time: () => number;
  present: () => Promise<void>;
  /** step, let streamed nodes land (≤ 5 s wall), draw: one round trip per video frame */
  frame: (dt: number) => Promise<boolean>;
}

export function installRecorder(app: App): Recorder {
  app.virtualTime = 0;
  let finished = false;
  let started = false;
  const rec: Recorder = {
    start: () => {
      if (started || !app.tour) return;
      started = true;
      // ?from=N starts at tour step N (to re-check one passage)
      void app.tour.play(Number(new URLSearchParams(location.search).get('from') ?? 0)).then(() => (finished = true));
    },
    step: (dt) => {
      app.virtualTime = (app.virtualTime ?? 0) + dt;
      app.engine.tick(dt);
      cssToVirtual(app.virtualTime);
      return finished;
    },
    time: () => app.virtualTime ?? 0,
    present: () => app.engine.present(),
    frame: async (dt) => {
      const done = rec.step(dt);
      const t0 = performance.now();
      while (app.nodes.stats.pending > 0 && performance.now() - t0 < 5000) await new Promise((r) => setTimeout(r, 4));
      await app.engine.present();
      return done;
    },
  };
  (window as unknown as { __rec: Recorder }).__rec = rec;
  return rec;
}

/**
 * CSS transitions and animations (subtitle fades, cards, the progress bar)
 * run on wall-clock time, which in ?record is many times slower than the
 * video. Pause each one when it appears and seek it on the virtual clock.
 */
const cssStart = new WeakMap<Animation, number>();
function cssToVirtual(now: number): void {
  for (const a of document.getAnimations()) {
    if (!cssStart.has(a)) {
      cssStart.set(a, now);
      a.pause();
    }
    a.currentTime = (now - cssStart.get(a)!) * 1000;
  }
}

/**
 * ?recordtab: record the guided tour on the demo machine with nothing but
 * Chrome. Tab capture (getDisplayMedia, the visitor confirms which tab) and
 * MediaRecorder at the display's real frame rate, interface and subtitles
 * included; the file downloads when the tour ends. Real time, so it needs a
 * GPU that keeps up (the RTX 5090 does); tools/record.mjs is the
 * frame-perfect alternative.
 */
export function installTabRecorder(app: App): void {
  const pick = ['video/mp4;codecs=avc1.640033', 'video/mp4', 'video/webm;codecs=vp9', 'video/webm'].find((t) => MediaRecorder.isTypeSupported(t)) ?? '';
  const panel = document.createElement('div');
  panel.className = 'rec-panel';
  panel.innerHTML = '<h3>录制导览视频</h3><p>点“开始”后，在浏览器弹出的窗口里选择<b>当前标签页</b>。导览会从头播放约三分半钟，结束后视频自动下载。录制期间请不要操作。</p>';
  const btn = document.createElement('button');
  btn.className = 'bench-btn';
  btn.textContent = '开始';
  panel.append(btn);
  document.body.append(panel);
  btn.onclick = async () => {
    const md = navigator.mediaDevices as MediaDevices & { getDisplayMedia: (o: object) => Promise<MediaStream> };
    let stream: MediaStream;
    try {
      stream = await md.getDisplayMedia({ video: { frameRate: 60 }, audio: false, preferCurrentTab: true, selfBrowserSurface: 'include' });
    } catch {
      btn.textContent = '没有获得录制权限，再试一次';
      return;
    }
    panel.remove();
    document.body.classList.add('recording');
    const rec = new MediaRecorder(stream, { mimeType: pick || undefined, videoBitsPerSecond: 25_000_000 });
    const chunks: Blob[] = [];
    rec.ondataavailable = (e) => e.data.size && chunks.push(e.data);
    const done = new Promise<void>((r) => (rec.onstop = () => r()));
    await new Promise((r) => setTimeout(r, 800)); // let the capture start before the first frame
    rec.start(1000);
    await app.tour?.play(0);
    await new Promise((r) => setTimeout(r, 1500));
    rec.stop();
    stream.getTracks().forEach((t) => t.stop());
    await done;
    document.body.classList.remove('recording');
    const ext = (rec.mimeType || pick).includes('mp4') ? 'mp4' : 'webm';
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob(chunks, { type: rec.mimeType || pick }));
    a.download = `星空的时间机器-导览.${ext}`;
    a.click();
  };
}
